import {stringify} from './core.mjs';
export function positionReviewControl(projectId,h){const {t,esc,btn}=h;return `<details class="position-review-control"><summary>${t('交给 Agent 核对记录','Review records with Agent')}</summary><p>${t('一次复制完整方案、本身份记录和核对要求，无需另附文件。','Copy the complete plan, identity record and review request together. No separate attachment is required.')}</p>${btn('position-brief',t('复制完整 Agent 指令','Copy complete Agent command'),'primary full',`data-id="${esc(projectId)}"`)}${btn('position-review',t('查看核对资料','View review material'),'text-link',`data-id="${esc(projectId)}"`)}</details>`;}
export function agentPacketDialog(bundle,packetId,h,reviewPackage=null){
 const {t,esc,btn,when,b,n}=h,e=bundle.position,m=bundle.manifest;
 const request=reviewPackage?.schema==='echo-launch-subscription-review/v1'?reviewPackage.requestedSubscription:null;
 const status=e?({none:t('暂无认购','No subscription'),reserved:t('已预留','Reserved'),refundable:t('可退款','Refundable'),refunded:t('已记退款','Refund recorded'),exited:t('已全部提前退出','Fully exited'),claimable:t('可领取','Claimable'),'pending-distribution':t('待派发','Awaiting distribution'),delivered:t('已记交付','Delivery recorded')}[e.status]??e.status):'';
 const button=(action,label,cls='secondary')=>btn(action,label,cls,`data-packet="${esc(packetId)}"`);
 return `<p>${request?t('复制一次完整指令，粘贴给 Agent 即可核对本次认购。认购金额、完整方案和本身份记录都已包含，无需另外下载文件。','Copy one complete command and paste it to your Agent. The requested amount, complete plan and identity record are included; no separate download is required.'):t('复制完整 Agent 指令即可核对；完整方案和本身份记录已包含，无需另外准备文件。','Copy the complete Agent command to review the included plan and identity record. No separate file is required.')}</p>${request?`<dl class="subscription-costs"><div><dt>${t('本次认购','Requested tokens')}</dt><dd>${n(request.quantity)} ${m.project.type==='nft'?t('枚 NFT','NFTs'):esc(m.project.symbol)}</dd></div><div><dt>${t('占公开认购额度','Of public allocation')}</dt><dd>${esc(request.publicAllocationPercent)}%</dd></div>${request.reservedTokenIds?`<div><dt>${t('预留 NFT 编号','Reserved NFT IDs')}</dt><dd>#${esc(request.reservedTokenIds.first)}–#${esc(request.reservedTokenIds.last)}</dd></div>`:''}<div><dt>${t('预计支付','Estimated payment')}</dt><dd>${b(request.paymentWei)} BNB<small>${t('Gas 另计 · 未估算','Gas separate · Not estimated')}</small></dd></div></dl>`:''}<dl class="facts"><div><dt>${t('项目','Project')}</dt><dd>${esc(m.project.name)}</dd></div><div><dt>${t('读取时间','Captured')}</dt><dd>${esc(when(bundle.capturedAt))}</dd></div>${e?`<div><dt>${t('本地记录状态','Local record status')}</dt><dd>${status}</dd></div><div><dt>${t('当前数量 / 本金','Active units / principal')}</dt><dd>${n(e.units)} / ${b(e.principalWei)} BNB</dd></div>`:''}</dl><div class="actions packet-actions">${button('packet-command',t('复制完整 Agent 指令','Copy complete Agent command'),'primary full')}</div><p class="muted">${t('粘贴后请 Agent 完成核对并报告结果。当前仅审核本地资料，不会连接钱包、签名或付款。资料过大无法完整粘贴时，可展开下方下载备份。','Paste it to your Agent for a read-only report. No wallet connection, signature or payment occurs. If the complete material is too large to paste, expand the optional download below.')}</p><details><summary>${t('可选下载与校验信息','Optional downloads & verification')}</summary><dl class="facts"><div><dt>${t('项目内容指纹','Project fingerprint')}</dt><dd class="mono break">${esc(m.configDigest)}</dd></div>${e?`<div><dt>${t('演示身份','Demo identity')}</dt><dd>${esc(e.identity)}</dd></div><div><dt>${t('本次记录指纹','Record snapshot fingerprint')}</dt><dd class="mono break">${esc(e.readSnapshot.snapshotDigest)}</dd></div>`:''}${reviewPackage?`<div><dt>${t('审核包指纹','Package fingerprint')}</dt><dd class="mono break">${esc(reviewPackage.packageDigest)}</dd></div>`:''}</dl><div class="actions">${button('packet-package',t('下载完整审核包 · 可选','Download review package · Optional'))}${button('packet-json',t('复制审核包 JSON','Copy review package JSON'))}${e?button('packet-position',t('下载本身份完整记录','Download complete identity record')):''}${button('packet-manifest',t('下载完整发行方案','Download complete launch plan'))}</div></details><details><summary>${t('查看完整 JSON','View complete JSON')}</summary><pre>${esc(stringify(reviewPackage??{launchPlan:m,identityRecord:e??null}))}</pre></details>`;
}
